#pragma once

#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <functional>
#include <memory>

namespace madcat::rhi
{
enum class ColorFormat { Presentation, Rgba16Float };
// Initial programmable graphics path: triangle list generated by vertex ID,
// one color attachment, no depth/blending, optional fragment sampled texture
// at set 0 (image binding 0, sampler binding 1), and 0..128 push constant bytes.
// Shader entry points are vertexMain/fragmentMain; layout is explicit, not reflected.
struct GraphicsPipelineDesc
{
    std::filesystem::path vertexShader, fragmentShader;
    ColorFormat colorFormat = ColorFormat::Presentation;
    bool sampledTexture = false;
    uint32_t pushConstantBytes = 0;
};
namespace detail { struct GraphicsPipelineState; struct GraphicsPipelineAccess; }
class GraphicsPipelineRef
{
public:
    GraphicsPipelineRef() = default;
    [[nodiscard]] explicit operator bool() const noexcept { return state_ != nullptr; }
private:
    friend struct detail::GraphicsPipelineAccess;
    std::shared_ptr<detail::GraphicsPipelineState> state_;
};
// Borrowed preparation service, valid only during the graph factory call.
// Returned immutable references may be owned by an algorithm's Prepared value.
// Keep them in the compiled Pass, so the frame graph retains them until commands
// retire. Reference counting alone does not establish GPU completion.
// Device is borrowed from the blocking runtime call: do not retain this factory
// or GPU references outside that call, or in captures that outlive its Device.
using GraphicsPipelineFactory = std::function<GraphicsPipelineRef(const GraphicsPipelineDesc&)>;
}
